'use strict';
const posterEditors=new WeakMap(),activePosterEditors=new Set(),posterURLs=new Map();
function posterContext(){return JSON.stringify([S.session?.user?.id,S.role,S.assignment?.branch_id,S.assignment?.district]);}
function announcementPoster(c){return c.poster_path?`<figure class="announcement-poster"><img data-content-poster="${e(c.poster_path)}" alt="${e(c.title)} announcement poster" loading="lazy" decoding="async"><figcaption data-poster-message>Loading poster…</figcaption></figure>`:'';}
async function posterURL(path){const key=posterContext()+':'+path,entry=posterURLs.get(key);if(entry&&entry.expires>Date.now())return entry.promise;const promise=signedUrl('occci-posters',path);posterURLs.set(key,{promise,expires:Date.now()+240000});try{return await promise;}catch(err){posterURLs.delete(key);throw err;}}
function loadAnnouncementPosters(){const context=posterContext();document.querySelectorAll('[data-content-poster]').forEach(async img=>{if(img.dataset.posterLoading)return;img.dataset.posterLoading='true';try{const url=await posterURL(img.dataset.contentPoster);if(!img.isConnected||posterContext()!==context)return;img.onload=()=>{const text=img.closest('figure').querySelector('[data-poster-message]');text.hidden=true;};img.onerror=()=>{const text=img.closest('figure').querySelector('[data-poster-message]');text.textContent='Poster unavailable. Reopen this page to try again.';text.hidden=false;};img.src=url;}catch{if(img.isConnected&&posterContext()===context)img.closest('figure').querySelector('[data-poster-message]').textContent='Poster unavailable. Reopen this page to try again.';}});}
function canManageAnnouncement(c){if(S.role==='Admin')return true;if(S.role==='BM')return Boolean(c.branch_id&&c.branch_id===S.assignment?.branch_id);if(S.role==='DM')return c.branch_id?S.branches.some(b=>b.id===c.branch_id&&b.district===S.assignment?.district):c.district===S.assignment?.district;return false;}
function contentPosterPicker(c){return `<section class="poster-picker full" data-poster-path="${e(c.poster_path||'')}" data-poster-original="${e(c.poster_original_path||'')}" data-poster-crop="${e(JSON.stringify(c.poster_crop||{zoom:1,x:0,y:0}))}" ${c.kind&&c.kind!=='Announcement'?'hidden':''}><div class="poster-picker-heading"><label>Announcement poster (optional)<input type="file" name="poster_file" accept="image/*" onchange="selectAnnouncementPoster(this)"></label><button type="button" class="outline small" data-poster-remove onclick="removeAnnouncementPoster(this)" ${c.poster_path?'':'hidden'}>Remove poster</button></div><p class="hint">The 16:9 preview matches the member home page. Drag the photo or use the crop controls. Photos up to 20 MB are converted to WebP, up to 300 KB per saved image.</p>${c.poster_path?`${announcementPoster(c)}<button type="button" class="outline small" data-poster-edit onclick="editAnnouncementPoster(this)">Adjust existing crop</button>`:''}<p data-poster-status role="status" class="smalltext" hidden></p><div class="poster-editor" data-poster-editor hidden><canvas width="960" height="540" tabindex="0" role="img" aria-label="Announcement poster crop. Drag or use arrow keys to position the photo." onpointerdown="dragAnnouncementPoster(event,this)" onkeydown="posterCropKey(event,this)"></canvas><div class="poster-controls"><label>Zoom<input type="range" data-poster-zoom min="1" max="3" step=".01" value="1" oninput="adjustAnnouncementPoster(this,'zoom')"></label><label>Horizontal position<input type="range" data-poster-x min="-1" max="1" step=".01" value="0" oninput="adjustAnnouncementPoster(this,'x')"></label><label>Vertical position<input type="range" data-poster-y min="-1" max="1" step=".01" value="0" oninput="adjustAnnouncementPoster(this,'y')"></label><button type="button" class="outline small" onclick="resetAnnouncementPoster(this)">Reset crop</button></div></div></section>`;}
function toggleAnnouncementPoster(form,kind){const root=form.querySelector('.poster-picker');if(root)root.hidden=kind!=='Announcement';}
function posterCropRect(width,height,zoom=1,x=0,y=0){const ratio=16/9,z=Math.max(1,Math.min(3,Number(zoom)||1)),baseWidth=Math.min(width,height*ratio),cw=baseWidth/z,ch=cw/ratio;return {sx:(width-cw)*(Math.max(-1,Math.min(1,Number(x)||0))+1)/2,sy:(height-ch)*(Math.max(-1,Math.min(1,Number(y)||0))+1)/2,width:cw,height:ch};}
function paintPoster(canvas,state){const ctx=canvas.getContext('2d');if(!ctx)throw Error('Your browser cannot crop this photo. Try a JPG or PNG.');const r=posterCropRect(state.img.naturalWidth||state.img.width,state.img.naturalHeight||state.img.height,state.zoom,state.x,state.y);ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(state.img,r.sx,r.sy,r.width,r.height,0,0,canvas.width,canvas.height);}
function drawAnnouncementPoster(root){const state=posterEditors.get(root);if(!state?.loaded)return;paintPoster(root.querySelector('canvas'),state);for(const key of ['zoom','x','y'])root.querySelector('[data-poster-'+key+']').value=state[key];state.changed=true;}
function releasePoster(root){const state=posterEditors.get(root);if(state){state.cancelled=true;if(state.url)URL.revokeObjectURL(state.url);}posterEditors.delete(root);activePosterEditors.delete(root);}
function cleanupAnnouncementPosters(){for(const root of activePosterEditors)if(!root.isConnected)releasePoster(root);}
function removeAnnouncementPoster(button){const root=button.closest('.poster-picker');releasePoster(root);root.dataset.posterRemoved='true';root.querySelector('[name=poster_file]').value='';root.querySelector('[data-poster-editor]').hidden=true;root.querySelector('[data-poster-remove]').hidden=true;root.querySelector('figure')?.remove();root.querySelector('[data-poster-edit]')?.remove();root.querySelector('[data-poster-status]').hidden=true;}
async function preparePoster(root,file,crop={zoom:1,x:0,y:0},originalPath=''){releasePoster(root);const state={file,zoom:crop.zoom||1,x:crop.x||0,y:crop.y||0,originalPath,loaded:false,cancelled:false,changed:false};posterEditors.set(root,state);activePosterEditors.add(root);const status=root.querySelector('[data-poster-status]');status.hidden=false;status.textContent='Preparing poster…';root.querySelector('[data-poster-editor]').hidden=true;state.ready=(async()=>{try{const source=await loadProfilePhoto(file);if(state.cancelled||!root.isConnected){URL.revokeObjectURL(source.url);return;}Object.assign(state,source,{loaded:true});root.dataset.posterRemoved='false';drawAnnouncementPoster(root);root.querySelector('[data-poster-editor]').hidden=false;root.querySelector('[data-poster-remove]').hidden=false;root.querySelector('figure')?.remove();status.textContent='Ready. This crop will appear on the member home page.';}catch(err){state.error=err;if(!state.cancelled)status.textContent=err.message;}})();await state.ready;}
async function selectAnnouncementPoster(input){const file=input.files?.[0];if(file)await preparePoster(input.closest('.poster-picker'),file);}
async function editAnnouncementPoster(button){button.disabled=true;const root=button.closest('.poster-picker'),context=posterContext();try{const path=root.dataset.posterOriginal;if(!path)throw Error('Upload the original photo to adjust its crop.');const url=await posterURL(path),response=await fetch(url);if(!response.ok)throw Error('Original poster could not be loaded.');const blob=await response.blob();if(!root.isConnected||posterContext()!==context)return;await preparePoster(root,new File([blob],'original.webp',{type:blob.type||'image/webp'}),JSON.parse(root.dataset.posterCrop),blob.type==='image/webp'&&blob.size<=300000?path:'');}catch(err){const text=root.querySelector('[data-poster-status]');text.hidden=false;text.textContent=err.message;}finally{button.disabled=false;}}
function adjustAnnouncementPoster(input,key){const root=input.closest('.poster-picker'),state=posterEditors.get(root);if(!state?.loaded)return;state[key]=Number(input.value);drawAnnouncementPoster(root);}
function resetAnnouncementPoster(button){const root=button.closest('.poster-picker'),state=posterEditors.get(root);if(!state?.loaded)return;Object.assign(state,{zoom:1,x:0,y:0});drawAnnouncementPoster(root);}
function posterCropKey(event,canvas){const key={ArrowLeft:['x',-.05],ArrowRight:['x',.05],ArrowUp:['y',-.05],ArrowDown:['y',.05]}[event.key];if(!key)return;event.preventDefault();const root=canvas.closest('.poster-picker'),state=posterEditors.get(root);if(!state?.loaded)return;state[key[0]]=Math.max(-1,Math.min(1,state[key[0]]+key[1]));drawAnnouncementPoster(root);}
function dragAnnouncementPoster(event,canvas){if(event.button!==undefined&&event.button!==0)return;const root=canvas.closest('.poster-picker'),state=posterEditors.get(root);if(!state?.loaded)return;event.preventDefault();const w=state.img.naturalWidth||state.img.width,h=state.img.naturalHeight||state.img.height,r=posterCropRect(w,h,state.zoom,state.x,state.y),box=canvas.getBoundingClientRect(),x=event.clientX,y=event.clientY,pointer=event.pointerId;canvas.setPointerCapture?.(pointer);const move=ev=>{if(ev.pointerId!==pointer||posterEditors.get(root)!==state)return;const sx=Math.max(0,Math.min(w-r.width,r.sx-(ev.clientX-x)*r.width/box.width)),sy=Math.max(0,Math.min(h-r.height,r.sy-(ev.clientY-y)*r.height/box.height));state.x=w===r.width?0:2*sx/(w-r.width)-1;state.y=h===r.height?0:2*sy/(h-r.height)-1;drawAnnouncementPoster(root);};const stop=ev=>{if(ev.pointerId!==pointer)return;for(const [name,fn] of [['pointermove',move],['pointerup',stop],['pointercancel',stop],['lostpointercapture',stop]])canvas.removeEventListener(name,fn);};canvas.addEventListener('pointermove',move);for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,stop);}
const POSTER_MAX_BYTES=300000;
async function posterBlob(state,original=false){const w=state.img.naturalWidth||state.img.width,h=state.img.naturalHeight||state.img.height,base=original?Math.min(1,2400/Math.max(w,h)):1;for(const scale of [1,.85,.7,.55,.4,.3,.2,.15]){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round((original?w*base:1200)*scale));canvas.height=original?Math.max(1,Math.round(h*base*scale)):Math.max(1,Math.round(canvas.width*9/16));if(original){const ctx=canvas.getContext('2d');if(!ctx)throw Error('Your browser cannot prepare this poster.');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(state.img,0,0,canvas.width,canvas.height);}else paintPoster(canvas,state);for(const quality of [.88,.8,.72,.64,.56]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',quality));if(!blob?.size)throw Error('This photo could not be converted. Try another image.');if(blob.type!=='image/webp')throw Error('This browser cannot export WebP. Please use an updated browser to upload the poster.');if(blob.size<=POSTER_MAX_BYTES)return new File([blob],original?'original.webp':'poster.webp',{type:'image/webp'});}}throw Error('The poster could not be reduced to 300 KB. Choose a simpler or smaller image.');}
async function saveAnnouncementContent(form,id,values,reason){if(!['Admin','DM','BM'].includes(S.role))throw Error('Only Admin, DM and BM can manage announcements.');const context=posterContext(),root=form.querySelector('.poster-picker'),old=S.content.find(c=>c.id===id)||{},v={...values,district:S.role==='DM'&&!values.branch_id?S.assignment.district:null,published:values.published==='true'};delete v.poster_file;delete v.reason;let path=old.poster_path||null,original=old.poster_original_path||null,crop=old.poster_crop||null;let state=root&&posterEditors.get(root);if(v.kind==='Announcement'&&old.poster_path&&!state&&root?.dataset.posterRemoved!=='true'&&(!/\.webp$/i.test(old.poster_path)||!/\.webp$/i.test(old.poster_original_path||''))){await editAnnouncementPoster(root.querySelector('[data-poster-edit]'));state=posterEditors.get(root);if(!state)throw Error('Upload the original photo again to convert this poster to WebP.');}if(v.kind!=='Announcement'||root?.dataset.posterRemoved==='true'){path=null;original=null;crop=null;}else if(state){await state.ready;if(state.error)throw state.error;if(state.cancelled||!state.loaded)throw Error('Please select the poster again.');const status=root.querySelector('[data-poster-status]');status.hidden=false;status.textContent='Converting to WebP and saving images, up to 300 KB each…';const recipe={zoom:state.zoom,x:state.x,y:state.y},signature=JSON.stringify([recipe.zoom,recipe.x,recipe.y]);if(!state.originalUpload)state.originalUpload=state.originalPath||await upload('occci-posters',await posterBlob(state,true));if(!state.displayUpload||state.uploadedCrop!==signature){state.displayUpload=await upload('occci-posters',await posterBlob({...state,...recipe}));state.uploadedCrop=signature;}original=state.originalUpload;path=state.displayUpload;crop=recipe;if(state.cancelled||posterEditors.get(root)!==state)throw Error('The poster changed while saving. Save again with the new photo.');}
 if(posterContext()!==context)throw Error('Your workspace changed. Reopen the announcement before saving.');
 if(path||old.poster_path||state||root?.dataset.posterRemoved==='true')return rpc('occci_save_content_poster',{record_id:id,values_json:v,poster_path:path,original_path:original,crop,reason});
 return rpc('occci_manage_record',{record_kind:'Content',record_id:id,values_json:v,remove_record:false,reason});
}
